const state={queue:[],id:null,detail:null,tab:'overview',page:'home',filter:'all',findingIndex:null,historyOpen:false,historyFilter:'all',historySource:null,historySourceId:null,reference:null,referenceCandidate:null,referenceLibrary:null,referenceDetail:null,matchResult:null,staticDemo:Boolean(location.hostname)&&!['localhost','127.0.0.1','[::1]'].includes(location.hostname),research:null};
const el=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label={escalate:'Needs closer review',review_required:'Needs judgement',routine_candidate:'Looks routine',blocked_extraction:'Analysis blocked'};
const decisionLabel={approve:'Approved by reviewer',request_amendment:'Amendment requested',reject:'Rejected by reviewer',escalate:'Escalated by reviewer'};
const filterLabel={all:'All contracts',escalate:'Needs closer review',review_required:'Needs judgement',routine_candidate:'Looks routine',blocked_extraction:'Analysis blocked'};
const validFilters=new Set(Object.keys(filterLabel));
const savedFilter=state.staticDemo?null:sessionStorage.getItem('chug.queueFilter');
if(validFilters.has(savedFilter))state.filter=savedFilter;
function queueItems(filter=state.filter){return state.queue.filter(item=>filter==='all'||(item.route===filter&&!item.latest_decision))}
function toast(message){el('toast').textContent=message;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el('toast').textContent='',5000)}
async function readJson(url,options){
  const response=await fetch(url,options);
  const type=(response.headers?.get('content-type')||'application/json').toLowerCase();
  if(!type.includes('json')){const error=new Error('Chug could not read the response for this page.');error.nonJson=true;throw error}
  let data;
  try{data=await response.json()}
  catch(cause){
    const error=new Error('Chug could not read the data for this page.');
    // Static hosting may return an empty 200 response for a missing Python API.
    // Only fall back to bundled data for an otherwise successful API response.
    error.nonJson=response.ok;
    throw error;
  }
  if(!response.ok)throw new Error(data?.error||'Chug could not load the data (error '+response.status+')');
  return data;
}
function staticJsonUrl(url){
  if(url==='/api/queue')return '/demo-data/queue.json';
  if(url==='/api/reference')return '/demo-data/reference.json';
  let match=url.match(/^\/api\/contracts\/([A-Za-z0-9_-]+)$/);
  if(match)return '/demo-data/contracts/'+match[1]+'.json';
  match=url.match(/^\/api\/history\/([A-Za-z0-9_-]+)$/);
  if(match)return '/demo-data/history/'+match[1]+'.json';
  if(url.startsWith('/demo-data/'))return url;
  throw new Error('This feature is not available in the public demo.');
}
function originalUrl(url){
  if(!state.staticDemo)return url;
  let match=url.match(/^\/api\/contracts\/([A-Za-z0-9_-]+)\/original$/);
  if(match)return '/demo-data/originals/contracts/'+match[1]+'.docx';
  match=url.match(/^\/api\/history\/([A-Za-z0-9_-]+)\/original$/);
  if(match)return '/demo-data/originals/history/'+match[1]+'.docx';
  match=url.match(/^\/api\/references\/([0-9a-f]{64})\/original$/);
  if(match)return '/demo-data/originals/references/'+match[1]+'.docx';
  return url;
}
async function api(url,options){
  if(state.staticDemo){
    if((options?.method||'GET').toUpperCase()!=='GET')throw new Error('Read-only public demo: you cannot upload files or save changes here.');
    return readJson(staticJsonUrl(url));
  }
  try{return await readJson(url,options)}
  catch(error){
    if(url==='/api/queue'&&!options&&error.nonJson){
      try{
        const snapshot=await readJson('/demo-data/queue.json');
        state.staticDemo=true;
        return snapshot;
      }catch(snapshotError){throw new Error('Chug could not load the public demo data. Please try again later.')}
    }
    throw error;
  }
}
function applyStaticDemo(){
  if(!state.staticDemo)return;
  document.body.classList.add('static-demo');
  if(el('incoming-upload'))el('incoming-upload').hidden=true;
  const shell=el('shell');
  if(shell&&!el('demo-banner'))shell.insertAdjacentHTML('beforebegin','<div id="demo-banner" role="status"><strong>Read-only demo</strong><span>All contracts are fictional. You can explore the reviews, but you cannot save changes or run new checks.</span></div>');
  document.querySelectorAll('.upload-button, [data-add-upload], .decision-action, [data-open-decision], [data-select-reference], [data-use-reference], form, #ai-run').forEach(node=>node.hidden=true);
  document.querySelectorAll('form').forEach(form=>{if(!form.dataset.publicNote){form.dataset.publicNote='true';form.insertAdjacentHTML('beforebegin','<p class="read-only-action-note">Unavailable on the public site. This static demonstration cannot save decisions or changes.</p>')}});
  document.querySelectorAll('a[href^="/api/"]').forEach(link=>{link.href=originalUrl(link.getAttribute('href'))});
}

async function loadQueue(){const data=await api('/api/queue');state.queue=data.items;renderQueue();if(state.page==='home'||state.page==='queue')renderPage()}
function renderQueue(){const shown=queueItems();el('filter').value=state.filter;el('queue-count').textContent=state.filter==='all'?`${state.queue.length} ${state.queue.length===1?'contract':'contracts'} · priority first`:`${shown.length} awaiting a decision`;el('queue').innerHTML=shown.map(item=>`<button class="queue-item ${item.id===state.id?'selected':''}" data-id="${esc(item.id)}" type="button"><span class="queue-item-top"><span class="queue-item-title">${esc(item.display_name)}</span><span class="route-label ${item.route}">${label[item.route]}</span></span><span class="queue-item-sub">${item.intake?esc(item.status.replaceAll('_',' ')):`${item.findings_count} ${item.findings_count===1?'finding':'findings'}`}${item.latest_decision?' · Decision recorded':''}</span><span class="queue-reason">${esc(item.reason)}</span></button>`).join('')||'<p class="empty">No contracts awaiting a decision in this view. Choose All contracts to see completed reviews.</p>';el('queue').querySelectorAll('[data-id]').forEach(button=>button.onclick=()=>select(button.dataset.id));applyStaticDemo()}
function route(){const parts=location.hash.slice(1).replace(/^\/+/, '').split('/');return {page:['home','queue','reference','help','explore','review','intake'].includes(parts[0])?parts[0]:'home',id:parts[1]?decodeURIComponent(parts[1]):null,tab:parts[2]||'overview',anchor:parts[3]?decodeURIComponent(parts[3]):null,findingIndex:parts[4]!==undefined&&/^\d+$/.test(parts[4])?Number(parts[4]):null}}
async function navigate(page,id=null,tab='overview',anchor=null,replace=false,findingIndex=null){if(page==='queue'){state.filter=validFilters.has(id)?id:'all';if(!state.staticDemo)sessionStorage.setItem('chug.queueFilter',state.filter)}const hash=page==='intake'&&id?'#intake/'+encodeURIComponent(id):page==='review'&&id?'#review/'+[id,tab,...(anchor?[anchor]:[]),...(findingIndex===null?[]:[String(findingIndex)])].map(encodeURIComponent).join('/'):page==='queue'&&state.filter!=='all'?'#queue/'+state.filter:'#'+page;if(location.hash!==hash)window.history[replace?'replaceState':'pushState'](null,'',hash);if(page==='review'&&id!==state.id){state.findingOpen=null;state.historyFilter='all'}state.page=page;state.findingIndex=findingIndex;state.historyOpen=false;state.historySource=null;if(page==='home'||page==='queue'){try{const data=await api('/api/queue');state.queue=data.items;renderQueue()}catch(err){el('workspace').innerHTML=`<p class="empty">${esc(err.message)}</p>`;return}}if(page==='intake'&&id){el('workspace').innerHTML='<div class="loading">Opening incoming review…</div>';try{state.intake=await api(`/api/intakes/${encodeURIComponent(id)}`)}catch(err){el('workspace').innerHTML=`<p class="empty">${esc(err.message)}</p>`;return}}if(page==='review'&&id){state.id=id;state.tab=tab;renderQueue();el('workspace').innerHTML='<div class="loading">Opening document…</div>';try{state.detail=await api(`/api/contracts/${encodeURIComponent(id)}`)}catch(err){el('workspace').innerHTML=`<p class="empty">${esc(err.message)}</p>`;return}}renderPage(anchor)}
async function select(id){const item=state.queue.find(row=>row.id===id);await navigate(item?.intake?'intake': 'review',item?.intake?item.intake_sha256:id)}
function setTab(tab,anchor,findingIndex=null){return navigate('review',state.id,tab,anchor,false,findingIndex)}
function sourceBox(unit,title,kind='source',finding=null){const unmatched=kind==='reference'&&!unit;const confirmedAbsent=unmatched&&finding?.category==='added_section';const heading=unmatched?'Reference document':title;const missing=confirmedAbsent?'<strong>No matching clause found</strong><p>This clause appears in the incoming contract but not in the reference. Check whether it’s acceptable.</p>':unmatched?'<strong>No clear match found</strong><p>Chug couldn’t confirm a matching passage in the reference. Check this wording against the full document.</p>':null;return `<div class="evidence-box"><h4>${esc(heading)}</h4>${unit?`<blockquote>${esc(unit.text)}</blockquote><a href="#${esc(unit.anchor)}" class="anchor-link" data-anchor="${esc(unit.anchor)}" data-kind="${kind}">View in full text →</a>`:missing||'<p>Provision absent from incoming document.</p>'}</div>`}
function findingSummary(f,index,d){const context=findingContext(d,f);return `<button class="finding-summary" type="button" data-open-comparison="${index}" data-anchor="${esc(f.sources[0]?.anchor||'')}"><span class="finding-summary-number" aria-hidden="true">${index+1}</span><span class="finding-summary-copy"><strong>${esc(f.title)}</strong>${context?`<small>${esc(context)}</small>`:''}</span><span class="finding-summary-arrow" aria-hidden="true">→</span></button>`}
function findingContext(d,f){const unit=f.sources[0];if(!unit)return '';const index=d.document.units.findIndex(item=>item.anchor===unit.anchor);const text=d.document.units.slice(Math.max(0,index-3),index).reverse().find(item=>/^\s*(?:schedule|annex|appendix|section|article|\d+(?:\.\d+)*\s)/i.test(item.text));const excerpt=unit.text.trim().replace(/\s+/g,' ');const wording=excerpt.length>70?`${excerpt.slice(0,67)}…`:excerpt;return [text?.text,wording].filter(Boolean).join(' · ')}
function findingView(f,index,brief=false){const d=state.detail;let related=f.related?.length?`<details class="related"><summary>Other provisions to consider (${f.related.length})</summary><div class="evidence-box">${f.related.map(u=>`<blockquote>${esc(u.text)}</blockquote><a href="#${esc(u.anchor)}" class="anchor-link" data-anchor="${esc(u.anchor)}" data-kind="source">View in full text →</a>`).join('')}</div></details>`:'';const lessons=(d.analysis.comparison_lessons||[]).filter(row=>row.finding_id===f.id);const sourceOptions=d.document.units.map(u=>`<option value="${esc(u.anchor)}" ${u.anchor===f.sources[0]?.anchor?'selected':''}>${esc(u.text.slice(0,85))}</option>`).join('');const referenceOptions=d.reference.units.map(u=>`<option value="${esc(u.anchor)}" ${u.anchor===f.reference?.anchor?'selected':''}>${esc(u.text.slice(0,85))}</option>`).join('');return `<details class="finding" id="finding-${index}"><summary><span class="finding-kind">${f.route==='escalate'?'Closer review':'Difference'}</span><span class="finding-title">${esc(brief?'More evidence and correction tools':f.title)}</span></summary><div class="finding-body"><h4>Why Chug flagged it</h4><p>${esc(f.explanation)}</p><div class="evidence-grid">${sourceBox(f.sources[0],'Incoming document')}${sourceBox(f.reference,'Reference wording','reference',f)}</div>${f.sources.length>1?`<details><summary>See ${f.sources.length-1} more source passages</summary>${f.sources.slice(1).map(u=>sourceBox(u,'Additional source')).join('')}</details>`:''}${related}${lessons.map(lesson=>`<div class="lesson"><strong>Past reviewer correction on related wording</strong><p>${esc(lesson.relationship.replaceAll('_',' '))}: ${esc(lesson.explanation)}</p><blockquote>${esc(lesson.previous_source_text)}</blockquote><p>Context: ${esc(lesson.context)} · Limits: ${esc(lesson.reuse_limits)}</p><p class="uncertainty">${esc(lesson.match_basis)}. Applicability ${esc(lesson.applicability)}. Current route and comparison are unchanged.</p><button class="text-action" data-precedent-source="${esc(lesson.previous_document_id)}" data-anchor="${esc(lesson.previous_source_anchor)}" type="button">Inspect original correction source →</button></div>`).join('')}${f.uncertainty?`<p class="uncertainty"><strong>What remains uncertain:</strong> ${esc(f.uncertainty)}</p>`:''}<details class="correction-details"><summary>Improve this comparison</summary><p>Your correction records how to read this comparison. It does not decide this contract or enter future search unless separately shared.</p><form class="correction-form" data-finding="${esc(f.id)}"><label class="field">Incoming passage<select name="source_anchor"><option value="">No incoming passage</option>${sourceOptions}</select></label><label class="field">Reference passage<select name="reference_anchor"><option value="">No reference passage</option>${referenceOptions}</select></label><label class="field">Your assessment<select name="relationship" required><option value="">Choose one</option><option value="wrong_pair">Wrong clause pairing</option><option value="equivalent_candidate">Possibly equivalent</option><option value="partial_overlap">Partial overlap</option><option value="material_difference">Material difference</option><option value="overlooked_exception">Overlooked exception</option><option value="unsure">Unsure</option></select></label><label class="field">What should a later reviewer check?<textarea name="explanation" required maxlength="2000"></textarea></label><label class="field">Reviewer name<input name="reviewer" required maxlength="100"></label><button class="secondary" type="submit">Save correction</button></form></details><details class="technical"><summary>Check detail</summary><p>${esc(f.method)} check · ${esc(f.id)}</p></details></div></details>`}
function reportMissView(d){if(d.analysis.route==='blocked_extraction')return '';const sourceOptions=d.document.units.map(u=>`<option value="${esc(u.anchor)}">${esc(u.text.slice(0,90))}</option>`).join('');const referenceOptions=d.reference.units.map(u=>`<option value="${esc(u.anchor)}">${esc(u.text.slice(0,90))}</option>`).join('');return `<details class="missed-report"><summary>Something Chug missed?</summary><p>Point to an incoming or reference passage and explain the concern. This records your challenge and prevents a routine route here; it does not approve or publish anything.</p><form class="correction-form" data-finding=""><label class="field">Incoming passage<select name="source_anchor"><option value="">None / missing from incoming</option>${sourceOptions}</select></label><label class="field">Reference passage<select name="reference_anchor"><option value="">None / not in reference</option>${referenceOptions}</select></label><input type="hidden" name="relationship" value="overlooked_exception"><label class="field">What was missed?<textarea name="explanation" required maxlength="2000"></textarea></label><label class="field">Reviewer name<input name="reviewer" required maxlength="100"></label><button class="secondary" type="submit">Record missed provision</button></form></details>`}
function precedentView(p){const published=p.kind==='published_demo';return `<article class="precedent"><div class="precedent-title"><span>${published?'Published demo precedent':'Historical case'} · ${esc(p.document_id)} · ${esc(p.decision.replaceAll('_',' '))}</span><span>${esc(p.date.slice(0,10))}</span></div><span class="match-basis">${esc(p.match_basis||'same clause topic')}</span><blockquote>${esc(p.source.text)}</blockquote><button class="text-action" type="button" data-precedent-source="${esc(p.document_id)}" data-anchor="${esc(p.source.anchor)}">Inspect original passage →</button><p><strong>Why shown:</strong> ${esc(p.why_retrieved)}</p><p><strong>Past rationale:</strong> ${esc(p.rationale)}</p>${published?`<p><strong>Decision conditions:</strong> ${esc(p.conditions||'None recorded')}</p><p><strong>Commercial context:</strong> ${esc(p.context)}</p><p><strong>Reuse limits:</strong> ${esc(p.reuse_authority)}</p><p class="uncertainty">Published by ${esc(p.authoriser)} for this local demonstration. Identity is self-attested; this is not policy or approval of this contract.</p>`:`<p><strong>Reuse:</strong> ${esc(p.reuse_authority)}</p><p class="uncertainty">The historical decision is for the whole contract. Its reuse authority is illustrative only.</p>`}</article>`}
function referencePassage(d,f){
  if(f.reference)return f.reference;
  for(const related of f.related||[]){const match=d.reference.units.find(unit=>unit.text===related.text);if(match)return match}
  return null
}
function overview(d){
  const a=d.analysis,first=a.findings[0],reference=first&&referencePassage(d,first);
  const summary=first?first.explanation:a.route==='blocked_extraction'?'The document could not be fully read. Comparison and independent checks did not finish.':a.reason==='Reviewer reported a possibly missed exception'?'A reviewer has challenged the comparison. Inspect the report in Review history before deciding.':a.route==='review_required'?'No wording difference was found within the supported checks, but this selected reference is not approved guidance. Review the reference before deciding.':'No material wording change was found by the completed checks. Confirm the parties and intended transaction.';
  const other=a.findings.slice(1),past=a.precedents[0];
  const additionNote=first&&!first.reference?(reference?'This wording is added to the incoming contract. The reference does not contain the addition; its applicable protection is shown alongside it.':'This wording is added to the incoming contract. No directly paired reference passage is available; inspect the linked provisions in the finding detail.'):'';
  const findings=a.findings||[],count=findings.length;
  return `<section class="review-focus ${a.route}" aria-labelledby="review-focus-title"><div class="focus-status"><span class="route-label ${a.route}">${label[a.route]}</span><span>${d.history.length?'Decision recorded':'Not reviewed yet'}</span></div><h3 id="review-focus-title" class="finding-headline">${count?`${count} ${count===1?'thing':'things'} to check`:esc(a.reason)}</h3><p class="focus-why">${count?`We’ve found ${count} ${count===1?'thing':'things'} worth looking at before you decide what to do.`:esc(summary)}</p>${findings.length?`<div class="finding-summaries" aria-label="Things to check">${findings.map((f,i)=>findingSummary(f,i,d)).join('')}</div>`:''}</section><section class="next-step" aria-labelledby="next-step-title"><div><h3 id="next-step-title" class="question-title">What should you do next?</h3><p>${d.history.length?'Review the recorded outcome or add a new human decision.':'Look at each item above, then make your own decision.'}</p></div><button class="primary decision-action" type="button" data-open-decision aria-controls="decision-section">${d.history.length?'Record another decision':'Record decision'}</button></section><details class="decision-disclosure" id="decision-section"><summary>Your decision</summary>${decisionView(d)}</details>${findings.length?`<details class="finding-tools"><summary>Where this came from, related provisions and check detail</summary><div class="finding-list">${findings.map((f,i)=>findingView(f,i)).join('')}</div></details>`:''}${past?`<details class="past-peek"><summary>Relevant past decision (${esc(past.decision.replaceAll('_',' '))})</summary><p>A related contract was reviewed in a different context; this is not permission to reuse that outcome.</p><button class="text-action" type="button" data-history-open>Inspect past decision</button></details>`:''}${reportMissView(d)}<details class="review-details"><summary>Optional AI comparison</summary>${aiView(d)}</details>`
}
function assuranceView(d){const a=d.analysis.assurance;const blocked=a.extraction.status==='blocked';return `<section class="support-panel assurance"><h3>What Chug checked</h3><p>${blocked?'Document content could not be fully accounted for. The remaining checks were not run.':'Checks were completed within the supported DOCX scope. This is evidence of work performed, not legal clearance.'}</p><ul class="check-list"><li>Original source <strong>${esc(a.source_integrity.status)} · SHA-256 ${esc(a.source_integrity.sha256.slice(0,12))}…</strong></li><li>Extraction <strong>${esc(a.extraction.status)} · ${esc(a.extraction.passages)} passages</strong></li><li>Compared with reference <strong>${esc(a.comparison.status)}${a.comparison.differences===null?'':` · ${a.comparison.differences} ${a.comparison.differences===1?"difference":"differences"}`}</strong></li><li>Other checks <strong>${esc(a.safeguards.status)}${a.safeguards.status==='complete'?` · ${a.safeguards.passages_examined} passages checked`:''}</strong></li><li>Things flagged for review <strong>${blocked?'not assessed':esc(a.escalation_indicators)}</strong></li><li>Human review <strong>${a.human_review.status==='not_recorded'?'Not reviewed yet':esc(a.human_review.status)}${a.human_review.last_decision?` · ${esc(a.human_review.last_decision.replaceAll('_',' '))}`:''}</strong></li></ul><details><summary>What was checked (and what wasn’t)</summary><p>Source: ${esc(a.source_integrity.bytes)} bytes · full SHA-256 <code>${esc(a.source_integrity.sha256)}</code></p><p>Parts accounted for: ${esc(a.extraction.parts.join(', ')||'none')}</p><p>Comparison: ${esc(a.comparison.scope||'not run')}</p><p>Other checks: ${esc(a.safeguards.scope||'not run')}</p>${a.limitations.length?`<ul>${a.limitations.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:''}<p>Open the full text for anchored passages, and download the original DOCX for its complete formatting and bytes.</p></details></section>`}
function aiView(d){let config=d.ai;const candidates=d.analysis.findings.filter(f=>f.sources.length&&f.reference);return `<section class="ai-box"><h3>Optional language comparison</h3><p>${esc(config.status)} · ${esc(config.provider)} ${esc(config.model)}. ${esc(config.transmission)} The route and human authority do not change based on this interpretation.</p>${config.available&&candidates.length?`<button class="secondary" id="ai-run" type="button" data-finding="${esc(candidates[0].id)}">Compare selected change with AI</button>`:''}${d.ai_results.map(r=>`<div class="ai-result"><strong>Live AI interpretation · ${esc(r.provider)} · ${esc(r.model)}</strong><p>${esc(r.summary)}</p><p>Possible effect: ${esc(r.possible_effect)}</p><p>Uncertainty: ${esc(r.uncertainty)}</p><small>${esc(r.timestamp)} · cited ${esc(r.source_anchors.join(', '))}</small></div>`).join('')}</section>`}
function decisionView(d){const marks=d.analysis.findings.length?`<fieldset class="considered"><legend>Findings you considered</legend><p>Select only those you inspected. Unselected findings remain visible in the review.</p>${d.analysis.findings.map(f=>`<label><input type="checkbox" name="finding" value="${esc(f.id)}"> ${esc(f.title)}</label>`).join('')}</fieldset>`:'';const intro=state.staticDemo?'Decisions happen in the private review workflow. This public demo cannot record a decision or approve a contract.':'Only a person can approve, request an amendment, reject or escalate. Your reason and the evidence you considered are saved in review history.';return `<section class="decision-panel"><h3>Your decision</h3><p>${intro}</p><form id="decision-form">${marks}<div class="form-row"><label class="field">Reviewer name<input name="reviewer" required maxlength="100" autocomplete="name"></label><label class="field">Decision<select name="decision" required><option value="">Choose a decision</option><option value="approve">Approve</option><option value="request_amendment">Request amendment</option><option value="reject">Reject</option><option value="escalate">Escalate</option></select></label></div><label class="field">Reason for decision<textarea name="rationale" required maxlength="2000" placeholder="What did you decide, and why?"></textarea></label><label class="field">Conditions, if any<textarea name="conditions" maxlength="1000" placeholder="Limits or actions agreed as part of this decision"></textarea></label><div class="form-footer"><span class="form-note">Recording a decision does not publish it as precedent.</span><button class="primary" type="submit">Record decision</button></div></form></section>`}
function fullText(d){let previous='';return `<p class="doc-meta">Exact extracted text with source anchors. For formatting, signatures and every original byte, open the DOCX. SHA-256: <code>${esc(d.document.sha256)}</code></p>${d.document.units.map(u=>{let heading=u.part!==previous?`<h3 class="document-part">${u.part==='word/document.xml'?'Document body':esc(u.part)}</h3>`:'';previous=u.part;return `${heading}<div class="document-unit" id="${esc(u.anchor)}"><span class="document-anchor">${esc(u.anchor)}</span><span class="document-text">${esc(u.text)}</span></div>`}).join('')}`}
function referenceTextView(d){return `<section class="selected-reference"><h3>Reference used for this review</h3><p>${esc(d.reference.filename)} is the bundled synthetic mutual NDA baseline bound to this precomputed review. The exact source identity is recorded below; the filename and comparison use do not establish current organisational approval.</p><p>SHA-256 <code>${esc(d.reference.sha256)}</code> · Extraction ${esc(d.reference.coverage?.status||'status unavailable')} · ${d.reference.units.length} anchored passages</p><a class="secondary" href="/api/references/${esc(d.reference.sha256)}/original">Download exact reference DOCX ↗</a></section>${fullText({document:d.reference})}`}
function historyView(d){const titles=new Map(d.analysis.findings.map(f=>[f.id,f.title]));return `<h3 class="section-title">Human decision history</h3><p class="history-intro">Decisions stay private to this review unless a demonstration publisher explicitly shares one for reuse. This local demo has no identity verification.</p><p class="quiet-note">Looking for recurring patterns? <a href="/decision-log.html?review=${encodeURIComponent(d.id)}">Explore fictional earlier decisions related to this review →</a>. These are illustrative scenarios, not recorded decisions on this document.</p>${d.history.length?d.history.map(e=>{const publications=d.publications.filter(p=>p.decision_id===e.id);const active=publications.some(p=>p.status==='active');const sources=e.considered_sources||[];const unique=[...new Map(sources.map(u=>[u.anchor,u])).values()];return `<article class="history-event"><strong>${esc(decisionLabel[e.decision])}</strong><small>${esc(e.reviewer)} · ${esc(e.timestamp)} · ${esc(e.sha256.slice(0,12))}…</small><p>${esc(e.rationale)}</p>${e.conditions?`<p><strong>Decision conditions:</strong> ${esc(e.conditions)}</p>`:''}<small>Considered: ${e.finding_ids.length?esc(e.finding_ids.map(id=>titles.get(id)||id).join('; ')):'none marked'} · Event ${esc(e.id)}</small>${publications.map(p=>`<div class="publication-status"><strong>${p.status==='active'?'Shared for reuse in this demo':'Withdrawn from active reuse'}</strong><p>Context: ${esc(p.context)}</p><p>Limits: ${esc(p.reuse_limits)}</p><small>Publisher ${esc(p.authoriser)} · ${esc(p.timestamp)} · Publication ${esc(p.id)}</small>${p.withdrawal?`<p>Withdrawn by ${esc(p.withdrawal.actor)}: ${esc(p.withdrawal.reason)}</p>`:`<details><summary>Withdraw this precedent</summary><form class="withdraw-form" data-publication="${esc(p.id)}"><label class="field">Your name<input name="actor" required maxlength="100"></label><label class="field">Reason for withdrawal<textarea name="reason" required maxlength="1000"></textarea></label><label class="acknowledge"><input type="checkbox" name="acknowledged" required> I am acting as the named demonstration publisher. This identity is not verified.</label><button class="secondary" type="submit">Withdraw from search</button></form></details>`}</div>`).join('')}${!active&&d.analysis.route!=='blocked_extraction'&&unique.length?`<details class="publish-details"><summary>Share this decision as a precedent</summary><p>Choose the exact wording considered. Sharing adds context for later reviewers; it never approves another contract or changes its route.</p><form class="publish-form" data-decision="${esc(e.id)}"><label class="field">Source passage<select name="source_anchor" required>${unique.map(u=>`<option value="${esc(u.anchor)}">${esc(u.text.slice(0,110))}${u.text.length>110?'…':''}</option>`).join('')}</select></label><label class="field">Demonstration publisher<input name="authoriser" required maxlength="100" placeholder="Name shown with this publication"></label><label class="field">Commercial context<textarea name="context" required maxlength="1000" placeholder="What situation made this decision applicable?"></textarea></label><label class="field">Limits on reuse<textarea name="reuse_limits" required maxlength="1000" placeholder="What must a later reviewer check before relying on this case?"></textarea></label><label class="acknowledge"><input type="checkbox" name="acknowledged" required> I am acting as a demonstration legal reviewer and have checked the source, decision and conditions. Identity is self-attested in this local prototype.</label><button class="primary" type="submit">Publish for demo reuse</button></form></details>`:!publications.length?`<p class="uncertainty">To share this decision, record a new decision with a source-linked finding marked as considered and complete extraction.</p>`:''}</article>`}).join(''):'<div class="empty">No human decision recorded for this exact document yet.</div>'}`}
function correctionHistoryView(d){return `<section class="correction-history"><h3 class="section-title">Comparison corrections</h3><p class="history-intro">These notes concern Chug's comparison, separately from legal decisions. An unshared note remains private to this review.</p>${d.corrections.length?d.corrections.map(c=>{const active=c.publications.some(p=>p.status==='active');return `<article class="history-event"><strong>${esc(c.relationship.replaceAll('_',' '))}</strong><small>${esc(c.reviewer)} · ${esc(c.timestamp)} · source ${esc(c.document_sha256.slice(0,12))}… · reference ${esc(c.reference_sha256.slice(0,12))}…</small><p>${esc(c.explanation)}</p><blockquote>${esc(c.source_text||'No incoming passage')}</blockquote><p>Reference: ${esc(c.reference_text||'No reference passage')}</p><small>Original Chug finding: ${esc(c.proposed_category)} · Event ${esc(c.id)}</small>${c.publications.map(p=>`<div class="publication-status"><strong>${p.status==='active'?'Shared as a comparison lesson':'Withdrawn from active reuse'}</strong><p>Context: ${esc(p.context)}</p><p>Limits: ${esc(p.reuse_limits)}</p><small>Publisher ${esc(p.publisher)} · ${esc(p.timestamp)}</small>${p.status==='active'?`<details><summary>Withdraw lesson</summary><form class="correction-withdraw-form" data-publication="${esc(p.id)}"><label class="field">Your name<input name="actor" required maxlength="100"></label><label class="field">Reason<textarea name="reason" required maxlength="1000"></textarea></label><label class="acknowledge"><input type="checkbox" name="acknowledged" required> I am acting as a demonstration legal reviewer; identity is self-attested.</label><button class="secondary" type="submit">Withdraw from search</button></form></details>`:''}</div>`).join('')}${!active&&d.analysis.route!=='blocked_extraction'?`<details class="publish-details"><summary>Share this correction for later reviews</summary><p>Only its evidence and your explanation are reused. Later applicability remains unverified.</p><form class="correction-publish-form" data-correction="${esc(c.id)}"><label class="field">Demonstration publisher<input name="publisher" required maxlength="100"></label><label class="field">Commercial context<textarea name="context" required maxlength="1000"></textarea></label><label class="field">Limits on reuse<textarea name="reuse_limits" required maxlength="1000"></textarea></label><label class="acknowledge"><input type="checkbox" name="acknowledged" required> I checked this correction and am acting as a demonstration legal reviewer. Identity is self-attested.</label><button class="primary" type="submit">Share comparison lesson</button></form></details>`:''}</article>`}).join(''):'<p class="empty">No comparison corrections recorded for this document.</p>'}</section>`}
function homeView(){
  const counts=Object.fromEntries(['escalate','review_required','routine_candidate','blocked_extraction'].map(key=>[key,queueItems(key).length]));
  const pending=state.queue.filter(item=>!item.latest_decision);
  const referenceKind=!state.reference?.current?'loading reference':state.reference.current.kind==='bundled'?'bundled mutual NDA sample':'selected synthetic mutual NDA reference';
  return `<section class="home"><h1>Review a contract</h1><p>Chug shows changes between a contract and its reference. You can check the wording and look at past decisions. You decide what happens next.</p><div class="home-actions"><button class="primary" type="button" data-start>${pending.length?'Start reviewing':'Open review queue'}</button></div><section class="home-work" aria-labelledby="home-work-title"><h2 id="home-work-title">Contracts to review</h2><div class="home-counts"><button type="button" class="summary-route" data-filter="escalate"><strong>${counts.escalate}</strong><span>Needs closer review</span><span aria-hidden="true">→</span></button><button type="button" class="summary-route" data-filter="review_required"><strong>${counts.review_required}</strong><span>Needs judgement</span><span aria-hidden="true">→</span></button><button type="button" class="summary-route" data-filter="routine_candidate"><strong>${counts.routine_candidate}</strong><span>Looks routine</span><span aria-hidden="true">→</span></button>${counts.blocked_extraction?`<button type="button" class="summary-route" data-filter="blocked_extraction"><strong>${counts.blocked_extraction}</strong><span>Analysis blocked</span><span aria-hidden="true">→</span></button>`:''}</div></section><div class="home-bottom"><p>These contracts are fictional. Chug does not approve contracts for you.</p><p>Reference for new uploads: <button class="text-action" type="button" data-page="reference">${referenceKind}</button>. Each review keeps the reference that Chug used when the review started.</p></div></section>`
}
function exploreView(){return `<section class="explore-page" aria-labelledby="explore-title"><button class="text-action explore-back" type="button" data-page="home">← Back to contract review</button><div class="explore-intro"><span class="eyebrow">Explore Chug</span><h1 id="explore-title">Review contracts now. Explore more ideas.</h1><p>Try the contract review demo. Compare fictional contracts with their references. Check the findings and earlier examples. The other tools below are ideas only.</p></div><section class="core-summary" aria-labelledby="core-title"><div><span class="eyebrow">Working foundation</span><h2 id="core-title">Chug finds changes. People decide.</h2></div><p>Chug keeps the original file and compares it with a reference. It shows changes and related decisions. The local version lets a reviewer record a decision. This public demo does not save decisions.</p></section><div class="workspace-heading"><div><span class="eyebrow">Available now</span><h2>Legal review</h2></div><p>Open a review using fictional contracts.</p></div><article class="workspace-card workspace-card-active"><div><span class="workspace-status">Working demo</span><h3>Legal · mutual NDAs</h3><p>Open a contract. Check a finding, read the original wording and look at past examples.</p></div><button class="primary" type="button" data-page="queue">Open legal review queue →</button></article><section class="future-workspaces" aria-labelledby="future-title"><div class="workspace-heading"><div><span class="eyebrow">Possible later work</span><h2 id="future-title">Other team workspaces</h2></div><p>These are ideas, not working tools. Each team would need its own documents, checks and people who can approve decisions.</p></div><div class="workspace-grid"><article class="workspace-card workspace-card-concept" aria-label="People and Culture: concept, not included in this demo"><h3>People &amp; Culture</h3><p>Compare policy updates with approved guidance and route exceptions to the right people.</p></article><article class="workspace-card workspace-card-concept" aria-label="Finance: concept, not included in this demo"><h3>Finance</h3><p>Review changes to recurring commercial terms against a controlled baseline.</p></article><article class="workspace-card workspace-card-concept" aria-label="Product and Engineering: concept, not included in this demo"><h3>Product &amp; Engineering</h3><p>Trace proposed changes to a technical standard and its earlier decisions.</p></article><article class="workspace-card workspace-card-concept" aria-label="Customer Support: concept, not included in this demo"><h3>Customer Support</h3><p>Bring a proposed response, relevant policy and prior resolutions together for human review.</p></article></div><p class="quiet-note">This demo does not use data from other teams. A decision by Legal does not apply to other teams.</p></section></section>`}
function queueView(){const shown=queueItems();return `<section class="queue-intro"><div><span class="eyebrow">Fictional contracts</span><h1>${filterLabel[state.filter]}</h1><p>${state.filter==='all'?'Open any review. Some have example decisions from earlier reviews.':`${shown.length} ${shown.length===1?'contract':'contracts'} awaiting a human decision in this category.`} These labels help you choose what to check. They do not approve a contract.</p></div><label class="queue-inline-filter">Show <select id="public-filter">${Object.entries(filterLabel).map(([key,name])=>`<option value="${key}" ${state.filter===key?'selected':''}>${name}</option>`).join('')}</select></label></section>${state.staticDemo?`<div class="public-queue" aria-label="Review queue">${shown.map(item=>`<button class="public-review-card" type="button" data-id="${esc(item.id)}"><span class="queue-item-top"><span class="queue-item-title">${esc(item.display_name)}</span><span class="route-label ${item.route}">${label[item.route]}</span></span><span class="queue-item-sub">${item.findings_count} ${item.findings_count===1?'finding':'findings'}${item.latest_decision?' · Fictional history available':''}</span><span class="queue-reason">${esc(item.reason)}</span><span class="open-review">Open review <span aria-hidden="true">→</span></span></button>`).join('')||'<p class="empty">No reviews match this filter. Choose All contracts to explore the full synthetic set.</p>'}</div>`:''}<p class="queue-human-note">${state.staticDemo?"A person must make each decision. This public demo cannot save decisions.":"Choose a contract to review. You can record a human decision in this local workspace."}</p>`}
function comparisonView(d){const findings=d.analysis.findings||[];const pane=(title,doc,kind)=>`<section class="comparison-column"><h3>${esc(title)}</h3><ol>${(doc.units||[]).map(unit=>{const linked=findings.map((f,index)=>({f,index})).filter(({f})=>kind==='source'?(f.sources||[]).some(u=>u.anchor===unit.anchor):f.reference?.anchor===unit.anchor);const text=`<span class="comparison-anchor">Source passage · ${esc(unit.anchor)}</span><span class="comparison-text">${esc(unit.text)}</span>`;return `<li>${linked.length?`<div class="comparison-unit has-finding" id="${esc(unit.anchor)}">${text}<div class="comparison-links">${linked.map(({f,index})=>`<button type="button" class="comparison-finding-link" data-open-comparison-finding="${index}">Open finding ${index+1}: ${esc(f.title)} →</button>`).join('')}</div></div>`:`<div class="comparison-unit" id="${esc(unit.anchor)}">${text}</div>`}</li>`}).join('')}</ol>${!(doc.units||[]).length?'<p class="empty">No wording was exported for this document.</p>':''}</section>`;return `<div class="comparison-heading"><div><h3>Compare documents</h3><p>Read the complete extracted wording. Highlighted passages link to Chug’s findings; other wording is shown without a claim that it is legally equivalent.</p></div><p>${findings.length} ${findings.length===1?'finding':'findings'} · ${d.document.units.length} incoming passages · ${d.reference.units.length} reference passages</p></div><div class="full-comparison">${pane('Incoming contract',d.document,'source')}${pane('Applicable reference',d.reference,'reference')}</div>${findings.length?`<section class="comparison-findings"><h3>Findings and evidence</h3><div class="finding-list">${findings.map((f,i)=>findingView(f,i)).join('')}</div></section>`:'<p class="empty">No findings were precomputed for this review. The full wording remains available above.</p>'}`}
function referenceView(){const current=state.reference?.current;const available=state.reference?.available||[];return `<section class="reference-page"><h1>Reference documents</h1><p>Chug compares each incoming contract with a reference document. This library shows the type, version and status of each fictional reference. In the local version, Legal can add new references. Chug can suggest a reference for a new contract, but a person must confirm the choice. Existing NDA reviews keep their original reference.</p>${state.staticDemo?'<p class="quiet-note">These are fictional examples. You can view the files, but you cannot upload or compare new contracts here.</p>':''}${referenceLibraryView()}${!state.staticDemo?`${current?`<section class="reference-library"><h2>Legacy NDA review binding</h2><p>Existing NDA reviews retain the exact reference they were created with.</p><div class="reference-card"><strong>${esc(current.filename)}</strong><span>${current.kind==='bundled'?'Legacy NDA comparison baseline':'Selected NDA reference'} · SHA-256 ${esc(current.sha256)}</span><span>Extraction ${esc(current.coverage.status)} · source ${esc(current.source_integrity)} · ${current.units.length} anchored passages</span><a href="/api/references/${esc(current.sha256)}/original">Download exact reference DOCX ↗</a></div></section>`:'<p class="loading">Loading current NDA reference…</p>'}<div class="home-actions"><label class="secondary upload-button">Add fictional Legal reference DOCX<input id="reference-upload" type="file" accept=".docx" hidden></label></div>${referenceCandidateView()}${available.length>1?`<div class="reference-options"><h2>Saved NDA references</h2>${available.filter(item=>item.sha256!==current?.sha256).map(item=>`<button class="secondary" type="button" data-select-reference="${esc(item.sha256)}">Use ${esc(item.filename)} (${item.kind==='bundled'?'legacy baseline':'uploaded synthetic'})</button>`).join('')}</div>`:''}${matchIntakeView()}<p class="quiet-note">Superseded and Withdrawn standards remain visible for provenance and cannot be proposed for a new match. Research candidates are not Active standards.</p>${current?`<details class="reference-full"><summary>Inspect current NDA wording</summary>${fullText({document:current})}</details>`:''}`:''}${state.staticDemo?researchView():''}</section>`}
function referenceCandidateView(){const file=state.referenceCandidate;return file?`<div class="reference-candidate"><strong>Selected: ${esc(file.name)}</strong><span>${(file.size/1024).toFixed(0)} KB · supported fictional standards enter the local library as Active for applicability proposals; upload does not compare or review the incoming contract</span><button class="primary" type="button" data-use-reference>Register standard</button><button class="text-action" type="button" data-cancel-reference>Cancel</button></div>`:''}
function matchIntakeView(){return `<section class="reference-library match-intake"><h2>Check reference applicability</h2><p>Upload a synthetic incoming DOCX to inspect its family and source evidence and receive a candidate proposal. This does not compare documents or enter the NDA review queue.</p><label class="secondary upload-button">Choose incoming DOCX<input id="match-upload" type="file" accept=".docx" hidden></label>${state.matchResult?matchResultView(state.matchResult):''}</section>`}
function matchResultView(result){const proposal=result.proposal||{};const candidate=proposal.proposal;const source=proposal.context?.dimensions||{};return `<article class="reference-detail match-result"><h3>Applicability proposal · ${esc(proposal.status||'unknown')}</h3><p>Incoming: ${esc(result.incoming?.filename)} · SHA-256 <code>${esc(result.incoming?.sha256)}</code> · assessed ${esc(result.assessed_at)}</p><p>${esc(proposal.reason||'No proposal reason recorded.')}</p>${candidate?`<p><strong>Suggested standard:</strong> ${esc(candidate.display_name)} · ${esc(candidate.status?.replaceAll('_',' ')||'status unavailable')} · version ${esc(candidate.version)} · ${esc(candidate.reference_id)} · SHA-256 <code>${esc(candidate.sha256)}</code></p><ul>${(candidate.reasons||[]).map(item=>`<li>${esc(item.dimension.replaceAll('_',' '))}: ${esc(item.value)}${(item.evidence||[]).map(e=>`<blockquote>${esc(e.text)} <small>${esc(e.anchor)}</small></blockquote>`).join('')}</li>`).join('')}</ul>`:''}${proposal.questions?.length?`<p><strong>Need to establish:</strong> ${esc(proposal.questions.join(' '))}</p>`:''}<details><summary>Context, alternatives and exclusions</summary><ul>${Object.entries(source).map(([name,item])=>`<li><strong>${esc(name.replaceAll('_',' '))}:</strong> ${esc(item.state)}${item.value?` · ${esc(item.value)}`:''}${(item.evidence||[]).map(e=>`<blockquote>${esc(e.text)} <small>${esc(e.anchor)}</small></blockquote>`).join('')}</li>`).join('')}</ul><h4>Alternatives</h4><ul>${(proposal.alternatives||proposal.eligible||[]).map(item=>`<li>${esc(item.display_name)} · ${esc(item.status||'')} · ${esc(item.version)} · ${esc(item.sha256)}</li>`).join('')||'<li>None</li>'}</ul><h4>Excluded</h4><ul>${(proposal.excluded||[]).map(item=>`<li>${esc(item.display_name)} · ${esc(item.status||'')} · ${esc((item.reasons||[]).join('; '))}</li>`).join('')||'<li>None</li>'}</ul></details><p>Human decision required. Confirmation and comparison have not occurred.</p><a href="${esc(result.original_url||('/api/reference-matches/'+result.incoming.sha256+'/original'))}">Download incoming original ↗</a></article>`}
function referenceLibraryView(){const localRows=state.referenceLibrary?.references||[];const publicRows=state.research?.references||[];const rows=localRows.length?localRows:publicRows.map(item=>({reference_id:item.id,display_name:item.name,family:item.family,status:'research_candidate',version:item.version,provenance:'synthetic_research_catalogue',source_integrity:'static_demo_source',sha256:item.sha256,download:item.download}));if(!rows.length)return `<section class="reference-library"><h2>Reference documents</h2><p>No reference documents are available in this demo.</p></section>`;const detail=state.referenceDetail;const applicability=detail?.applicability||{};const label=value=>({bundled_demo_baseline:'Bundled demo baseline',verified_research_catalogue:'Synthetic research catalogue',synthetic_research_catalogue:'Synthetic research catalogue',locally_uploaded_synthetic_reference:'Fictional Legal upload'}[value]||value||'Source not recorded');const showRow=item=>`<li><div><strong>${esc(item.display_name)}</strong><span>${esc(item.family.replaceAll('_',' '))} · ${esc((item.status||'unknown').replaceAll('_',' '))} · version ${esc(item.version||'unknown')}</span><small>Source: ${esc(label(item.provenance))} · ${esc(item.source_integrity||'source integrity unavailable')} · SHA-256 ${esc(item.sha256)}</small></div>${item.download?`<a href="${esc(item.download)}" download>Original DOCX ↗</a>`:!state.staticDemo?`<button type="button" class="text-action" data-reference-detail="${esc(item.reference_id)}">View details</button>`:''}</li>`;const baselines=rows.filter(item=>item.status==='legacy_nda_baseline');const candidates=rows.filter(item=>item.status==='research_candidate');const standards=rows.filter(item=>!['legacy_nda_baseline','research_candidate'].includes(item.status));return `<section class="reference-library"><h2>Reference documents</h2><p>Check what each document is for, where it came from and whether Chug can use it.</p>${standards.length?`<h3>References added by Legal</h3><ul>${standards.map(showRow).join('')}</ul>`:''}${baselines.length?`<h3>Original NDA reference</h3><p>Existing reviews still use this reference. Chug will not suggest it for new contracts until someone confirms its purpose and scope.</p><ul>${baselines.map(showRow).join('')}</ul>`:''}${candidates.length?`<h3>Examples for testing — not reference documents</h3><p>${candidates.length} fictional examples. Chug does not use these as references for new contracts.</p><ul>${candidates.map(showRow).join('')}</ul>`:''}${detail?`<details class="reference-detail" open><summary>${esc(detail.display_name)} · ${esc(detail.status.replaceAll('_',' '))}</summary><p>Family: ${esc(detail.family)} · Status: ${esc(detail.status)} · Version: ${esc(detail.version)} · Provenance: ${esc(label(detail.provenance))}</p><p>Original: ${esc(detail.original_filename)} · SHA-256 <code>${esc(detail.sha256)}</code> · source ${esc(detail.source_integrity)}</p>${detail.scope?`<p>Scope: ${esc(detail.scope)}${detail.scope_anchor?` · source ${esc(detail.scope_anchor)}`:''}</p>`:''}<details><summary>Applicability and source evidence</summary><ul>${Object.entries(applicability).map(([name,item])=>`<li><strong>${esc(name.replaceAll('_',' '))}:</strong> ${esc(item.state)}${item.value?` · ${esc(item.value)}`:''}${(item.evidence||[]).map(evidence=>`<blockquote>${esc(evidence.text)} <small>${esc(evidence.anchor)}</small></blockquote>`).join('')}</li>`).join('')}</ul></details><p>Extraction: ${esc(detail.extraction.status)} · ${detail.extraction.passage_count} passages · ${detail.extraction.limitations.length?`Limitations: ${esc(detail.extraction.limitations.join('; '))}`:'No extraction limitations recorded.'}</p><a href="${esc(detail.original_url)}">Download exact original DOCX ↗</a>${detail.kind==='uploaded_synthetic'&&detail.status==='active'?`<form class="reference-status-form" data-reference-status="superseded"><label class="field">Reason to supersede<input name="reason" required maxlength="1000"></label><button class="secondary" type="submit">Mark Superseded</button></form><form class="reference-status-form" data-reference-status="withdrawn"><label class="field">Reason to withdraw<input name="reason" required maxlength="1000"></label><button class="secondary" type="submit">Mark Withdrawn</button></form>`:''}${detail.status_history?.length?`<details><summary>Status history</summary><ul>${detail.status_history.map(event=>`<li>${esc(event.from)} → ${esc(event.to)} · ${esc(event.timestamp)} · ${esc(event.reason)}</li>`).join('')}</ul></details>`:''}</details>`:''}</section>`}
function researchView(){
  const r=state.research;
  if(!r)return '';
  const entries=(rows)=>rows.map(item=>'<li><strong>'+esc(item.name)+'</strong> <span class="research-meta">'+esc(item.family||item.status||'Unassessed')+'</span> <a href="'+esc(item.download)+'" download>Original DOCX</a></li>').join('');
  return '<section class="research-library"><h2>Example contracts — not references</h2>'+
    '<p>These fictional contracts are for testing. Chug has not checked or compared them.</p>'+
    '<details open><summary>'+r.routine_clients.length+' client contract examples (not checked)</summary><ul>'+entries(r.routine_clients)+'</ul></details>'+
    '<details><summary>'+r.challenge_cases.length+' examples with possible problems (not checked)</summary><ul>'+entries(r.challenge_cases)+'</ul></details>'+
    '<p class="quiet-note">These files are only examples. Chug has not checked them. You cannot start a new review on the public site.</p></section>';
}
function helpView(){return `<section class="help-page"><h1>How Chug works</h1><p>Chug helps a reviewer compare an incoming contract with the reference selected for that review. It shows differences and evidence. A person decides what happens next.</p><h2>Use the public demo</h2><ol><li>Open the review queue. Select a fictional contract.</li><li>Start on Review. Chug shows how many things need checking and why they were flagged.</li><li>Open Compare documents to read the incoming wording beside the reference wording. Use each finding link to move between the comparison and the review.</li><li>Check the full document, reference and checks run when you need more evidence.</li><li>Decide what you would do: approve, request an amendment, reject or escalate. The public demo shows the review process but cannot save a decision.</li></ol><h2>How references work</h2><p>A reference is the document Chug uses as the comparison baseline for a review. It is not an automatic approval rule.</p><p>The reference library can contain different contract families and versions. In the local workflow, Chug can suggest a suitable active reference for a new contract. A person must confirm that the reference applies before relying on that comparison. Existing reviews keep the exact reference they used when the review started.</p><p>The public References page also contains fictional testing examples. These are clearly marked and are not reference documents.</p><h2>What the labels mean</h2><dl><dt>Needs closer review</dt><dd>Chug found wording or missing protection that could matter. Check the evidence and original wording.</dd><dt>Needs judgement</dt><dd>Chug found a change or uncertainty that needs a person to assess it.</dd><dt>Looks routine</dt><dd>Chug completed its supported checks without finding a material difference. A person must still review the contract and decide.</dd><dt>Analysis blocked</dt><dd>Chug could not complete the required extraction or comparison. Do not treat the review as complete.</dd></dl><h2>What Chug checks</h2><p>Chug keeps the source identity, extracts supported DOCX content, compares it with the selected reference and shows the passages behind each finding. The Checks run tab shows what completed and what did not.</p><p>Past decisions and reviewer corrections can provide context. They do not automatically decide a new contract.</p><h2>What the public demo cannot do</h2><p>The public site is read-only. You cannot upload a new contract, add or change a reference, confirm reference applicability, save a reviewer correction or record a contract decision.</p><p>The local version includes those workflow tools. A human reviewer remains responsible for approval, amendment, rejection or escalation. Optional AI comparison cannot approve a contract or change the human decision boundary.</p><p><button class="text-action" type="button" data-page="explore">See other ideas for Chug →</button></p></section>`}

function historyDrawer(d){const scope=d.analysis.history_scope||{historical_records:0,active_published_records:0};const choices=[...new Set(d.analysis.precedents.map(row=>row.decision))];const shown=state.historyFilter==='all'?d.analysis.precedents:d.analysis.precedents.filter(row=>row.decision===state.historyFilter);return `<aside class="history-drawer" role="complementary" aria-label="Similar past decisions"><div class="drawer-head"><div><h3>Similar past decisions</h3><p>${d.analysis.precedents.length} related shown · ${scope.historical_records} historical + ${scope.active_published_records} published records searched</p></div><button type="button" class="secondary" data-history-close>Close</button></div><p class="quiet-note">Wording and topic are matched lexically. A past decision does not approve this contract.</p><label class="history-filter">Show <select id="history-filter"><option value="all">All related decisions</option>${choices.map(value=>`<option value="${esc(value)}" ${state.historyFilter===value?'selected':''}>${esc(value.replaceAll('_',' '))}</option>`).join('')}</select></label>${shown.map(precedentView).join('')||'<p class="empty">No related case with that decision.</p>'}${state.historySource?`<section class="history-source"><h4>Original reviewed contract · ${esc(state.historySource.document.filename)}</h4><a href="/api/history/${esc(state.historySourceId)}/original">Download exact historical DOCX ↗</a>${fullText(state.historySource)}<button class="text-action" type="button" data-source-close>Close original</button></section>`:''}</aside>`}
function intakeView(d){const proposal=d.matching?.proposal||{},candidate=proposal.proposal,analysis=d.analysis,confirmation=d.reference_confirmation||{};const evidence=(candidate?.reasons||[]).map(row=>`<li><strong>${esc(row.dimension.replaceAll('_',' '))}:</strong> ${esc(row.value)}${(row.evidence||[]).map(e=>`<blockquote>${esc(e.text)} <small>${esc(e.anchor)}</small></blockquote>`).join('')}</li>`).join('');const observations=d.comparison?.observations||[];const findings=analysis?.findings||d.comparison?.findings||observations.map(f=>({id:f.id,title:f.title,explanation:f.explanation,sources:f.incoming_passages||[],reference:f.reference_passages?.[0]}));const hasComparison=d.comparison.status==='analysed'||d.comparison.status==='complete';const analysisIncomplete=d.extraction?.status!=="complete"||!hasComparison;return `<div class="doc-head"><div><button class="text-action" type="button" data-return-queue>← Back to review queue</button><h2>${esc(d.document.filename)}</h2><p class="doc-context">Incoming ${esc(d.family||'family unresolved')} · ${esc(d.status.replaceAll('_',' '))} · A person decides reference applicability and the contract.</p></div></div><section class="notice ${esc(d.route)}"><div class="notice-top"><span class="eyebrow">${esc(d.status.replaceAll('_',' '))}</span><span class="route-label ${esc(d.route)}">${label[d.route]}</span></div><h3>${esc(d.reason)}</h3><p>Extraction: ${esc(d.extraction.status)}. Original SHA-256 <code>${esc(d.incoming.sha256)}</code>.</p>${d.source_integrity?.reference&&d.source_integrity.reference!=='verified'&&d.source_integrity.reference!=='not_linked'?`<p class="notice blocked_extraction"><strong>Reference source ${esc(d.source_integrity.reference)}.</strong> This saved comparison snapshot remains historical evidence; the current reference original is not verified. Review the original files before relying on it.</p>`:''}</section>${analysisIncomplete?`<section class="notice blocked_extraction" role="alert"><strong>Analysis incomplete · no quick-review result</strong><p>Extraction: ${esc(d.extraction.status)}. Comparison: ${esc(d.comparison.status)}. ${esc(d.comparison.reason||"The required comparison did not run.")} Independently inspect the exact incoming original before deciding.</p></section>`:""}<section><h3 class="section-title">Reference applicability</h3>${candidate?`<article class="evidence-box"><h4>${confirmation.status==='confirmed'?'Confirmed reference':'Chug selected this reference · check applicability'}</h4><p><strong>${esc(candidate.display_name)}</strong> · ${esc(candidate.reference_id)} · version ${esc(candidate.version)} · SHA-256 <code>${esc(candidate.sha256)}</code></p><p>${esc(proposal.reason)}</p>${evidence?`<ul>${evidence}</ul>`:''}${candidate.gaps?.length?`<p class="uncertainty">Open applicability facts: ${esc(candidate.gaps.join(' '))}</p>`:''}${proposal.alternatives?.length?`<p class="uncertainty">Other compatible references considered: ${esc(proposal.alternatives.map(item=>item.display_name).join(', '))}.</p>`:''}<p class="uncertainty">Proposal status: ${esc(proposal.status)}. ${confirmation.status==='confirmed'?`Applicability confirmed by ${esc(confirmation.reviewer)} · ${esc(confirmation.timestamp)}. Reason: ${esc(confirmation.rationale)}`:'This is a provisional match. Check that the reference applies before relying on the comparison.'}</p></article>${confirmation.status!=='confirmed'&&['proposed','proposed_with_gaps'].includes(proposal.status)?`<form class="decision-panel intake-confirmation-form" data-incoming="${esc(d.incoming.sha256)}" data-reference="${esc(candidate.reference_id)}" data-reference-sha="${esc(candidate.sha256)}"><h3>Confirm this reference</h3><p>This confirms only the comparison baseline. It does not approve the incoming contract.</p><label class="field">Reviewer name<input name="reviewer" required maxlength="100"></label><label class="field">Why does it apply here?<textarea name="rationale" required maxlength="2000"></textarea></label><button class="secondary" type="submit">${hasComparison?"Confirm reference applicability":"Confirm reference and compare"}</button></form>`:''}`:`<p class="empty">${esc(proposal.reason||'No suitable reference was established.')}</p>`}</section><section><h3 class="section-title">Comparison</h3>${hasComparison?`<p>${d.family==='customer_order'?'Deterministic customer-order comparison · check the proposed reference and its applicability.':'Deterministic provisional NDA comparison · a person must confirm reference applicability and review the result.'} Human review required.</p>${findings.length?`<div class="finding-list">${findings.map(f=>`<article class="finding"><div class="finding-body"><strong>${esc(f.title)}</strong><p>${esc(f.explanation)}</p><div class="evidence-grid"><div class="evidence-box"><h4>Incoming · ${esc(f.sources?.[0]?.anchor||'source')}</h4><blockquote>${esc(f.sources?.[0]?.text||'No incoming excerpt')}</blockquote></div><div class="evidence-box"><h4>Reference · ${esc(f.reference?.anchor||'comparison anchor')}</h4><blockquote>${esc(f.reference?.text||'No corresponding reference wording')}</blockquote></div></div>${f.sources?.slice(1).map(s=>`<p>${esc(s.anchor)} · ${esc(s.text)}</p>`).join('')||''}</div></article>`).join('')}</div>`:'<p>No textual or structural differences were reported by this comparison; this does not approve the contract.</p>'}<p class="uncertainty">${(d.comparison.limitations||[]).map(esc).join(' ')}</p>`:`<div class="notice review_required"><h3>Comparison not run</h3><p>${esc(d.comparison.reason)}</p></div>`}</section><section class="decision-panel"><h3>Record your review decision</h3><p>Append-only record linked to this exact incoming file hash. This records your decision; it does not publish precedent.</p>${d.human_decision?.status==='recorded'?`<p>Last recorded: ${esc(d.human_decision.outcome.replaceAll('_',' '))} by ${esc(d.human_decision.last_decision.reviewer)} · ${esc(d.human_decision.last_decision.timestamp)}</p>`:''}<form class="intake-decision-form" data-incoming="${esc(d.incoming.sha256)}"><p class="notice blocked_extraction">Before recording approval, independently inspect the exact incoming original above. Confirm this review before approval, including when analysis is blocked or has not run.</p><label class="acknowledge"><input type="checkbox" name="independent_original_reviewed"><span>I independently reviewed the exact incoming original document.</span></label><label class="field">Reviewer name<input name="reviewer" required maxlength="100"></label><label class="field">Decision<select name="decision" required><option value="">Choose one</option><option value="approve">Approve</option><option value="request_amendment">Request amendment</option><option value="reject">Reject</option><option value="escalate">Escalate</option></select></label><label class="field">Rationale<textarea name="rationale" required maxlength="2000"></textarea></label><label class="field">Conditions, if any<textarea name="conditions" maxlength="1000"></textarea></label><button class="primary" type="submit">Record decision</button></form></section><section class="support-grid"><div><h3 class="section-title">Next action</h3><p>${d.status==='awaiting_reference'?'Chug could not select a reliable reference. Review the source and clarify which standard applies.':'A reviewer must inspect the proposed reference, compare relevant provisions, and decide what to do next.'}</p><p>No automated route makes a legal decision.</p></div><div><h3 class="section-title">Original source</h3><p>${esc(d.document.units.length)} extracted passages · coverage ${esc(d.extraction.status)}</p><a class="secondary" href="${esc(d.original_url)}">Download exact incoming DOCX ↗</a></div></section><details class="document-details"><summary>Inspect extracted source passages</summary>${d.document.units.map(u=>`<div class="document-unit"><span class="document-anchor">${esc(u.anchor)}</span><span class="document-text">${esc(u.text)}</span></div>`).join('')}</details>`}
function startReviewing(){const next=state.page==='queue'?queueItems()[0]:state.queue.find(item=>!item.latest_decision);if(!next)return navigate('queue');if(state.page==='home'){state.filter=next.route;if(!state.staticDemo)sessionStorage.setItem('chug.queueFilter',next.route)}return select(next.id)}
function renderPage(anchor){el('shell').className='shell page-'+state.page;document.title=state.page==='explore'?'Explore Chug · Potential workspaces':'Chug · Contract review';document.querySelectorAll('.main-nav [data-page]').forEach(button=>button.setAttribute('aria-current',button.dataset.page===state.page||(state.page==='review'&&button.dataset.page==='queue')?'page':'false'));if(state.page==='home')el('workspace').innerHTML=homeView();else if(state.page==='queue')el('workspace').innerHTML=queueView();else if(state.page==='intake')el('workspace').innerHTML=state.intake?intakeView(state.intake):'<p class="empty">Incoming review unavailable.</p>';else if(state.page==='reference')el('workspace').innerHTML=referenceView();else if(state.page==='help')el('workspace').innerHTML=helpView();else if(state.page==='explore')el('workspace').innerHTML=exploreView();else render();document.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>navigate(button.dataset.page));document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>navigate('queue',button.dataset.filter));document.querySelectorAll('[data-start]').forEach(button=>button.onclick=startReviewing);el('workspace').querySelectorAll('.public-review-card').forEach(button=>button.onclick=()=>select(button.dataset.id));const publicFilter=el('workspace').querySelector('#public-filter');if(publicFilter)publicFilter.onchange=event=>navigate('queue',event.target.value);document.querySelectorAll('[data-add-upload]').forEach(button=>button.onclick=()=>el('upload').click());const referenceUpload=el('reference-upload');if(referenceUpload)referenceUpload.onchange=uploadReference;const matchUpload=el('match-upload');if(matchUpload)matchUpload.onchange=uploadForMatch;const useReference=el('workspace').querySelector('[data-use-reference]');if(useReference)useReference.onclick=commitReference;const cancelReference=el('workspace').querySelector('[data-cancel-reference]');if(cancelReference)cancelReference.onclick=()=>{state.referenceCandidate=null;renderPage()};document.querySelectorAll('[data-select-reference]').forEach(button=>button.onclick=()=>chooseReference(button.dataset.selectReference));document.querySelectorAll('[data-reference-detail]').forEach(button=>button.onclick=async()=>{try{state.referenceDetail=await api('/api/reference-library/'+encodeURIComponent(button.dataset.referenceDetail));renderPage()}catch(err){toast(err.message)}});el('workspace').querySelectorAll('.reference-status-form').forEach(form=>form.onsubmit=updateReferenceStatus);el('workspace').querySelectorAll('[data-return-queue]').forEach(button=>button.onclick=()=>navigate('queue',state.filter));el('workspace').querySelectorAll('.intake-confirmation-form').forEach(form=>form.onsubmit=submitIntakeConfirmation);el('workspace').querySelectorAll('.intake-decision-form').forEach(form=>{const decision=form.querySelector('[name=decision]'),reviewed=form.querySelector('[name=independent_original_reviewed]');if(decision&&reviewed)decision.onchange=()=>{reviewed.required=decision.value==='approve'};form.onsubmit=submitIntakeDecision});applyStaticDemo();if(anchor)requestAnimationFrame(()=>{const target=document.getElementById(anchor);target?.classList.add('evidence-focus');target?.scrollIntoView({behavior:'smooth',block:'center'})})}
function reviewNav(d){const count=d.analysis.findings.length;return `<div class="review-nav"><nav class="tabs" aria-label="Review evidence and tools"><button class="tab ${state.tab==='overview'?'active':''}" data-tab="overview" ${state.tab==='overview'?'aria-current="page"':''}>Review</button><button class="tab ${state.tab==='comparison'?'active':''}" data-tab="comparison" ${state.tab==='comparison'?'aria-current="page"':''}>Compare documents</button><button class="tab ${state.tab==='document'?'active':''}" data-tab="document" ${state.tab==='document'?'aria-current="page"':''}>Full document</button><button class="tab ${state.tab==='reference'?'active':''}" data-tab="reference" ${state.tab==='reference'?'aria-current="page"':''}>Reference</button><button class="tab ${state.tab==='assurance'?'active':''}" data-tab="assurance" ${state.tab==='assurance'?'aria-current="page"':''}>Checks run</button><button class="tab ${state.tab==='history'?'active':''}" data-tab="history" ${state.tab==='history'?'aria-current="page"':''}>Review history${d.history.length||d.corrections.length?` (${d.history.length+d.corrections.length})`:''}</button></nav>${count?`<span class="review-finding-count">${count} ${count===1?'thing':'things'} to check</span>`:''}</div>`}
function render(){
  const d=state.detail;if(!d)return;
  const content=state.tab==='overview'?overview(d):state.tab==='comparison'?comparisonView(d):state.tab==='assurance'?assuranceView(d):state.tab==='document'?fullText(d):state.tab==='reference'?referenceTextView(d):state.tab==='history'?historyView(d)+correctionHistoryView(d):'<p class="empty">This review view is not available in the exported snapshot.</p>';
  el('workspace').innerHTML=`<div class="doc-head"><div><button class="text-action" type="button" data-return-queue>← Back to ${state.filter==='all'?'review queue':filterLabel[state.filter].toLowerCase()}</button><h2>${esc(d.display_name)}</h2><p class="doc-context">Compared with the reference selected for this review · A person decides what happens next.</p></div></div><details class="document-details"><summary>Document details and original files</summary><p>Incoming: ${esc(d.id)} · ${esc(d.document.filename)} · SHA-256 <code>${esc(d.document.sha256)}</code></p><p>Applicable reference: ${esc(d.reference.filename)} · SHA-256 <code>${esc(d.reference.sha256)}</code>. Existing reviews retain their selected reference.</p><a href="/api/contracts/${encodeURIComponent(d.id)}/original">Download original DOCX ↗</a></details>${reviewNav(d)}${content}${state.historyOpen?historyDrawer(d):''}`;
  el('workspace').querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>setTab(button.dataset.tab));
  el('workspace').querySelectorAll('[data-open-comparison]').forEach(button=>button.onclick=()=>setTab('comparison',button.dataset.anchor,Number(button.dataset.openComparison)));
  el('workspace').querySelectorAll('[data-open-comparison-finding]').forEach(button=>button.onclick=()=>{const index=Number(button.dataset.openComparisonFinding);setTab('comparison',button.closest('.comparison-unit').id,index)});
  el('workspace').querySelectorAll('[data-return-queue]').forEach(button=>button.onclick=()=>navigate('queue',state.filter));
  el('workspace').querySelectorAll('a[data-anchor]').forEach(link=>link.onclick=event=>{event.preventDefault();state.findingOpen=link.closest('.finding')?.id||state.findingOpen;setTab(link.dataset.kind==='reference'?'reference':'document',link.dataset.anchor)});
  el('workspace').querySelectorAll('[data-precedent-source]').forEach(button=>button.onclick=async()=>{try{const id=button.dataset.precedentSource;if(id.startsWith('H')){state.historySource=await api(`/api/history/${encodeURIComponent(id)}`);state.historySourceId=id;render();const target=document.getElementById(button.dataset.anchor);target?.classList.add('evidence-focus');target?.scrollIntoView({behavior:'smooth',block:'center'})}else{await select(id);setTab('document',button.dataset.anchor)}}catch(err){toast(err.message)}});
  el('workspace').querySelectorAll('[data-source-close]').forEach(button=>button.onclick=()=>{state.historySource=null;state.historySourceId=null;render()});
  el('workspace').querySelectorAll('[data-open-finding]').forEach(button=>button.onclick=()=>{const target=el('finding-'+button.dataset.openFinding);target.open=true;target.scrollIntoView({behavior:'smooth',block:'center'})});
  if(state.tab==='comparison'&&state.findingIndex!==null){const target=el(`finding-${state.findingIndex}`);if(target){target.open=true;requestAnimationFrame(()=>target.scrollIntoView({behavior:'smooth',block:'center'}))}}
  el('workspace').querySelectorAll('[data-open-decision]').forEach(button=>button.onclick=()=>{el('decision-section').open=true;el('decision-section').scrollIntoView({behavior:'smooth',block:'start'});el('decision-section').querySelector('summary')?.focus({preventScroll:true})});
  el('workspace').querySelectorAll('[data-history-open]').forEach(button=>button.onclick=()=>{state.historyOpen=true;render();el('workspace').querySelector('[data-history-close]')?.focus()});
  el('workspace').querySelectorAll('[data-history-close]').forEach(button=>button.onclick=()=>{state.historyOpen=false;render();el('workspace').querySelector('[data-history-open]')?.focus()});
  const historyFilter=el('history-filter');if(historyFilter)historyFilter.onchange=event=>{state.historyFilter=event.target.value;state.historySource=null;state.historySourceId=null;render()};
  el('workspace').querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>navigate(button.dataset.page));
  const form=el('decision-form');if(form)form.onsubmit=submitDecision;
  el('workspace').querySelectorAll('.publish-form').forEach(form=>form.onsubmit=submitPublication);
  el('workspace').querySelectorAll('.withdraw-form').forEach(form=>form.onsubmit=submitWithdrawal);
  el('workspace').querySelectorAll('.correction-form').forEach(form=>form.onsubmit=submitCorrection);
  el('workspace').querySelectorAll('.correction-publish-form').forEach(form=>form.onsubmit=submitCorrectionPublication);
  el('workspace').querySelectorAll('.correction-withdraw-form').forEach(form=>form.onsubmit=submitCorrectionWithdrawal);
  const ai=el('ai-run');if(ai)ai.onclick=()=>runAI(ai.dataset.finding)
  if(state.findingOpen&&state.tab==='overview'){const open=el(state.findingOpen);if(open)open.open=true}
  applyStaticDemo();
}
async function submitDecision(event){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);try{await api('/api/decisions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({document_id:state.id,reviewer:data.get('reviewer'),decision:data.get('decision'),rationale:data.get('rationale'),conditions:data.get('conditions'),finding_ids:data.getAll('finding')})});toast('Human decision recorded with this document hash.');state.detail=await api(`/api/contracts/${encodeURIComponent(state.id)}`);await loadQueue();setTab('history')}catch(err){toast(err.message)}}
async function submitPublication(event){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);try{await api('/api/precedents',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({document_id:state.id,decision_id:form.dataset.decision,source_anchor:data.get('source_anchor'),authoriser:data.get('authoriser'),context:data.get('context'),reuse_limits:data.get('reuse_limits'),role:'demo_legal_reviewer',acknowledged:data.get('acknowledged')==='on'})});state.detail=await api(`/api/contracts/${encodeURIComponent(state.id)}`);setTab('history');toast('Shared as a demonstration precedent. Later reviews still need a human decision.')}catch(err){toast(err.message)}}
async function submitWithdrawal(event){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);try{await api(`/api/precedents/${encodeURIComponent(form.dataset.publication)}/withdraw`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({actor:data.get('actor'),reason:data.get('reason'),role:'demo_legal_reviewer',acknowledged:data.get('acknowledged')==='on'})});state.detail=await api(`/api/contracts/${encodeURIComponent(state.id)}`);setTab('history');toast('Precedent withdrawn from active search; history retained.')}catch(err){toast(err.message)}}
async function submitCorrection(event){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);try{await api('/api/corrections',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({document_id:state.id,finding_id:form.dataset.finding,source_anchor:data.get('source_anchor'),reference_anchor:data.get('reference_anchor'),relationship:data.get('relationship'),explanation:data.get('explanation'),reviewer:data.get('reviewer')})});await loadQueue();await setTab('history');toast('Comparison correction saved. It is not a legal decision or reusable lesson.')}catch(err){toast(err.message)}}
async function submitCorrectionPublication(event){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);try{await api('/api/correction-lessons',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({correction_id:form.dataset.correction,publisher:data.get('publisher'),context:data.get('context'),reuse_limits:data.get('reuse_limits'),role:'demo_legal_reviewer',acknowledged:data.get('acknowledged')==='on'})});state.detail=await api(`/api/contracts/${encodeURIComponent(state.id)}`);setTab('history');toast('Comparison lesson shared for later reviews. It cannot change routing or approve a contract.')}catch(err){toast(err.message)}}
async function submitCorrectionWithdrawal(event){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);try{await api(`/api/correction-lessons/${encodeURIComponent(form.dataset.publication)}/withdraw`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({actor:data.get('actor'),reason:data.get('reason'),role:'demo_legal_reviewer',acknowledged:data.get('acknowledged')==='on'})});state.detail=await api(`/api/contracts/${encodeURIComponent(state.id)}`);setTab('history');toast('Comparison lesson withdrawn from active search; its history remains.')}catch(err){toast(err.message)}}
async function runAI(findingId){if(!confirm('Send the selected synthetic source and reference passages to OpenAI for an optional language comparison? This may incur API charges within configured caps.'))return;try{await api('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({document_id:state.id,finding_id:findingId})});state.detail=await api(`/api/contracts/${encodeURIComponent(state.id)}`);render();toast('Live AI interpretation received.')}catch(err){toast(err.message)}}
async function chooseReference(sha256){const selected=state.reference?.available.find(item=>item.sha256===sha256);if(!selected)return;try{state.reference=await api('/api/reference/select',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sha256})});renderPage();toast('Reference selected for new incoming uploads. Existing reviews keep their original reference.')}catch(err){toast(err.message)}}
async function submitIntakeConfirmation(event){event.preventDefault();const form=event.currentTarget,data=new FormData(form);try{const result=await api(`/api/intakes/${encodeURIComponent(form.dataset.incoming)}/reference-confirmation`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reference_id:form.dataset.reference,reference_sha256:form.dataset.referenceSha,reviewer:data.get('reviewer'),rationale:data.get('rationale')})});state.intake=result;await loadQueue();renderPage();toast('Reference applicability recorded. The family-specific comparison is available for review.')}catch(err){toast(err.message)}}
async function submitIntakeDecision(event){event.preventDefault();const form=event.currentTarget,data=new FormData(form);try{await api(`/api/intakes/${encodeURIComponent(form.dataset.incoming)}/decisions`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reviewer:data.get('reviewer'),decision:data.get('decision'),rationale:data.get('rationale'),conditions:data.get('conditions'),finding_ids:[],independent_original_reviewed:data.get('independent_original_reviewed')==='on'})});state.intake=await api(`/api/intakes/${encodeURIComponent(form.dataset.incoming)}`);await loadQueue();renderPage();toast('Human decision recorded against this exact incoming source.')}catch(err){toast(err.message)}}
function uploadReference(event){const file=event.target.files[0];event.target.value='';if(!file)return;if(!file.name.toLowerCase().endsWith('.docx')){toast('Choose a synthetic DOCX reference.');return}state.referenceCandidate=file;renderPage()}
async function commitReference(){const file=state.referenceCandidate;if(!file)return;const form=new FormData();form.append('file',file);try{const result=await api('/api/reference/upload',{method:'POST',body:form});state.reference=result;if(!state.staticDemo)state.referenceLibrary=await api('/api/reference-library');state.referenceDetail=result.library_item?await api('/api/reference-library/'+encodeURIComponent(result.library_item.reference_id)):null;state.referenceCandidate=null;renderPage();const selected=result.library_item?.sha256===result.current?.sha256;toast(result.library_item?.family==='customer_order'?'Customer-order standard registered Active; NDA baseline unchanged.':selected?'NDA standard registered Active and selected for new NDA uploads.':'Existing reference identity retained; selected baseline unchanged.')}catch(err){toast(err.message)}}
async function uploadForMatch(event){const file=event.target.files[0];event.target.value='';if(!file)return;if(!file.name.toLowerCase().endsWith('.docx')){toast('Choose a synthetic DOCX contract.');return}const form=new FormData();form.append('file',file);try{const result=await api('/api/reference-matches',{method:'POST',body:form});state.matchResult=await api('/api/reference-matches/'+encodeURIComponent(result.incoming.sha256));renderPage();toast('Applicability proposal saved. No comparison or contract decision was made.')}catch(err){toast(err.message)}}
async function updateReferenceStatus(event){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);try{await api('/api/reference-library/'+encodeURIComponent(state.referenceDetail.reference_id)+'/status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:form.dataset.referenceStatus,reason:data.get('reason')})});state.referenceLibrary=await api('/api/reference-library');state.referenceDetail=await api('/api/reference-library/'+encodeURIComponent(state.referenceDetail.reference_id));renderPage();toast('Reference status saved; its original and prior matches remain traceable.')}catch(err){toast(err.message)}}
el('filter').onchange=event=>navigate('queue',event.target.value);el('upload-trigger').onclick=()=>el('upload').click();el('upload').onchange=async event=>{const file=event.target.files[0];if(!file)return;const form=new FormData();form.append('file',file);try{const data=await api('/api/intakes',{method:'POST',body:form});await loadQueue();await navigate('intake',data.incoming.sha256);toast(data.comparison.status==='not_run'?'No reliable reference was found. Review the suggested next step.':'Chug selected a reference and compared the documents. Human review is still required.')}catch(err){toast(err.message)}event.target.value=''};
window.addEventListener('popstate',()=>{const next=route();navigate(next.page,next.id,next.tab,next.anchor,true,next.findingIndex)});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.historyOpen){state.historyOpen=false;render();el('workspace').querySelector('[data-history-open]')?.focus()}});
loadQueue().then(async()=>{state.reference=await api('/api/reference');if(state.staticDemo){try{state.research=await api('/demo-data/research.json')}catch(error){console.warn('Research fixtures are not exported:',error.message)}}else{try{state.referenceLibrary=await api('/api/reference-library')}catch(error){console.warn('Reference library could not be loaded:',error.message)}}const next=route();await navigate(next.page,next.id,next.tab,next.anchor,true,next.findingIndex)}).catch(err=>el('workspace').innerHTML=`<p class="empty">Could not load the local workspace: ${esc(err.message)}</p>`);
